    bolsilloazul: () => g(0, 1, 1, F.bolsa(K.bl)) + r(-4, 0, 8, 6, 1, '#1a3f8f') + B(7.5, -7.5, 0.34, F.estrellita(K.ye)),
    cartablanca: () => r(-7.5, -10.5, 15, 21, 2.2, K.wh) + r(-5.5, -8.5, 11, 17, 1.2, '#e8e4dc') + B(5, 6, 0.5, F.moneda()),
    rebarajar: () => g(0, 0, 0.8, F.carta('trebol', K.gr)) + s('M-10 -3 A10 10 0 0 1 8 -6 M8 -6 L4 -7.5 M8 -6 L8.5 -2', K.go, 2) + s('M10 3 A10 10 0 0 1 -8 6 M-8 6 L-4 7.5 M-8 6 L-8.5 2', K.go, 2),
    parejaganadora: () => g(-4.5, 0, 0.8, F.carta('corazon', K.re), -12) + g(4.5, 0, 0.8, F.carta('corazon', K.re), 12),
    cajafuerte: () => r(-10, -9, 20, 18, 2.5, K.sd) + r(-8, -7, 16, 14, 1.5, K.st) + c(0, 0, 4.5, K.sd) + s('M0 0 L3 -3', K.dk, 1.8) + B(7, 7, 0.4, F.moneda()),
    cobrador: () => d('M-9 -6 C-9 -9 -6 -10 -4 -9 L-2 -5 C-1.5 -4 -2 -3 -3 -2.5 C-2 1 1 4 3.5 5 C4 4 5 3.5 6 4 L9.5 6 C10.5 8 9 10.5 6.5 10 C-3 8.5 -9 2 -9 -6Z', K.cr) + B(6, -6, 0.5, F.moneda()),
    naipedorado: () => g(0, 0, 1, F.carta('corona', K.go)) + B(-8, -8, 0.3, F.estrellita(K.ye)) + B(8.5, 8.5, 0.28, F.estrellita(K.ye)),
